const summariseAccessByEmailHash = `-- name: SummariseAccessByEmailHash :many
SELECT
    kind,
    COUNT(*)::bigint AS event_count,
    MIN(created_at)::timestamptz AS first_at,
    MAX(created_at)::timestamptz AS last_at,
    COUNT(DISTINCT ip)::bigint AS distinct_ips
FROM access_events
WHERE email_hash = $1
GROUP BY kind
`

type SummariseAccessByEmailHashRow struct {
	Kind        string
	EventCount  int64
	FirstAt     pgtype.Timestamptz
	LastAt      pgtype.Timestamptz
	DistinctIps int64
}

func (q *Queries) SummariseAccessByEmailHash(ctx context.Context, emailHash pgtype.Text) ([]*SummariseAccessByEmailHashRow, error) {
	rows, err := q.db.Query(ctx, summariseAccessByEmailHash, emailHash)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*SummariseAccessByEmailHashRow
	for rows.Next() {
		var i SummariseAccessByEmailHashRow
		if err := rows.Scan(
			&i.Kind,
			&i.EventCount,
			&i.FirstAt,
			&i.LastAt,
			&i.DistinctIps,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

